LOAD spatial;

-- Compass bearing (degrees, clockwise from north) between every hub pair.
-- Return: from_ap, to_ap, bearing_deg (1dp) ordered by from_ap, to_ap

setup:
CREATE TABLE hubs AS SELECT * FROM (VALUES
  ('JFK', ST_Point(-73.7781, 40.6413)),
  ('LAX', ST_Point(-118.408, 33.9425)),
  ('MIA', ST_Point(-80.2870, 25.7959)),
  ('SEA', ST_Point(-122.309, 47.4502))
) t(code, geom);
